package com.leetcode.algorithms;

public class AddDigits {
    public static void main(String[] args) {
	System.out.println("Input: 38; Output: " + addDigits(38));
    }

    // Time: O(logn)
    // Space: O(1)
    public static int addDigits(int num) {
	if (num == 0) {
	    return 0;
	} else {
	    int result = 0;
	    while (num > 0) {
		result += num % 10;
		num = num / 10;
		if (num == 0 && result > 9) {
		    num = result;
		    result = 0;
		}
	    }
	    return result;
	}
    }
}
