 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    public int countUnivalSubtrees(TreeNode root) {
	return dfs(root, -1, -1);
    }

    private int dfs(TreeNode node, int f, int s) {
	if (node == null) return 0;
	if ((f == -1 || f == node.val) && (s == -1 || s == node.val) &&
	    (node.left == null || node.left.val == node.val) &&
	    (node.right == null || node.right.val == node.val)) {
	    return 1 + dfs(node.left, node.val, node.val) +
		dfs(node.right, node.val, node.val);
	}
