	sorted.addAll(numbers);
	Collections.sort(sorted);

	for (int i = 1; i < sorted.size(); i++) {
	    if (sorted.get(i) - sorted.get(i - 1) <= threshold) {
		return true;
	    }
	}

	return false;
    }
