import math

class List:
    def __init__(self, lst):
        self.lst = lst

    def get_list(self):
        return self.lst

    def merge(self, left, right):
        i = 0
        j = 0
        result = []
        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1
        result += left[i:]
        result += right[j:]
        return result

    def _merge_sort(self, lst):
        if len(lst) <= 1:
            return lst
        mid = math.floor(len(lst) / 2)
        left = self._merge_sort(lst[:mid])
        right = self._merge_sort(lst[mid:])
        return self.merge(left, right)

    def merge_sort(self):
        self.lst = self._merge_sort(self.lst)

    def is_sorted(self):
        for i in range(len(self.lst) - 1):
            if self.lst[i] > self.lst[i + 1]:
                return False
        return True

