package com.lintcode.dp;

public class BurstBalloons {
    public int maxCoins(int[] nums) {
        // write your code here
        int len = nums.length;
        int[][] dp = new int[len][len];
        for (int i = 0; i < len; i++) {
            for (int j = 0; j < len; j++) {
                dp[i][j] = Integer.MIN_VALUE;
            }
        }
        return maxCoins(nums, dp, 0, len - 1);
    }

    private int maxCoins(int[] nums, int[][] dp, int start, int end) {
        if (start > end) {
            return 0;
        }
        if (dp[start][end]!= Integer.MIN_VALUE) {
            return dp[start][end];
        }
        for (int i = start; i <= end; i++) {
            int left = (start - 1 < 0? 1 : nums[start - 1]) * nums[i] * (end + 1 < nums.length? nums[end + 1] : 1);
            int right = (end + 1 >= nums.length? 1 : nums[end + 1]) * nums[i] * (start - 1 < 0? 1 : nums[start - 1]);
            int leftMax = maxCoins(nums, dp, start, i - 1);
            int rightMax = maxCoins(nums, dp, i + 1, end);
            dp[start][end] = Math.max(dp[start][end], left + right + leftMax + rightMax);
        }
        return dp[start][end];
    }
}
public class Main {
    public static void main(String[] args) {
        Solution s = new Solution();
        List<Boolean> correct = Arrays.asList(
                s.greatestCommonDivisor(3, 7) == 1,
                s.greatestCommonDivisor(10, 15) == 5,
                s.greatestCommonDivisor(49, 14) == 7,
                s.greatestCommonDivisor(144, 60) == 12
        );
        if (correct.contains(false)) {
            throw new AssertionError();
        }
    }
}

