class Solution {
    public int findMaxConsecutive(int[] arr) {
	int max = 0;
	ArrayList<Integer> curr = new ArrayList<Integer>();
	for (int i = 0; i < arr.length; i++) {
	    if (curr.size() == 0) curr.add(arr[i]);
	    else if (arr[i] == curr.get(curr.size() - 1)) curr.add(arr[i]);
	    else {
		curr.clear();
		curr.add(arr[i]);
	    }
	    if (curr.size() > max) max = curr.size();
	}
	return max;
    }
}

