    public boolean hasUniqueCharacters(String str) {
        Set<Character> characters = new HashSet<Character>();
        for (int i = 0; i < str.length(); i++) {
            if (characters.contains(str.charAt(i))) {
                return false;
            } else {
                characters.add(str.charAt(i));
            }
        }
        return true;
    }

