    def findDisappearedNumbers(self, nums):
        """
        :type nums: List[int]
        :rtype: List[int]
        """
        count = [0] * len(nums)
        for i in range(len(nums)):
            count[nums[i] - 1] += 1
        return [i + 1 for i, v in enumerate(count) if v == 0]

