     */
    private String reverse(String s) {
	return new StringBuilder(s).reverse().toString();
    }
    /**
     * change base 10 to other bases
     */
    public String changeBaseTen(int x, int base) {
	int sum = 0;
	int pow = 1;
	while (x > 0) {
	    sum += (x % base) * pow;
	    pow *= 10;
	    x /= base;
	}
	return Integer.toString(sum);
    }
}
