    /**
    Return median of elements in the list l.
    >>> median(Arrays.asList(3, 1, 2, 4, 5))
    3
    >>> median(Arrays.asList(-10, 4, 6, 1000, 10, 20))
    15.0
     */
    public double median(List<Integer> l) {
	int len = l.size();
	Collections.sort(l);
	if (len % 2 == 0) {
	    return (l.get(len / 2) + l.get(len / 2 - 1)) / 2.0;
	} else {
	    return l.get(len / 2);
	}
    }

    /**
    Returns the product of every element in the list l.
    >>> product(Arrays.asList(1, 2, 3))
    6
    >>> product(Arrays.asList(3, 2, 1))
    6
     */
    public int product(List<Integer> l) {
	int product = 1;
	for (Integer i : l) {
	    product *= i;
	}
	return product;
    }

    /**
    Given a base b and an exponent e, calculate the integer value of b^e.
    >>> power(2, 3)
    8
    >>> power(5, 2)
    25
     */
    public int power(int b, int e) {
	int result = 1;
	for (int i = 0; i < e; i++) {
	    result *= b;
	}
	return result;
    }

    /**
