    ""
    >>> longestConsecutive("z")
    "z"
     */
    public String longestConsecutive(String text) {
	int len = text.length();
	if (len <= 1) return text;
	ArrayList<Character> list = new ArrayList<Character>();
	for (int i = 0; i < len; i++) {
	    list.add(text.charAt(i));
	}
	Collections.sort(list);
	int max = 1;
	int count = 1;
	int curr = 1;
	char prev = list.get(0);
	for (int i = 1; i < len; i++) {
	    char currChar = list.get(i);
