class Solution {
    /**
    Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic(Arrays.asList(1, 2, 4, 20))
    true
    >>> monotonic(Arrays.asList(1, 20, 4, 10))
    false
    >>> monotonic(Arrays.asList(4, 1, 0, -10))
    true
     */
    public boolean monotonic(List<Integer> l) {
	int n = l.size();
	if (n == 0) return true;
	int i = 1;
	int prev_diff = l.get(1) - l.get(0);
	while (i < n && prev_diff == 0) {
	    prev_diff = l.get(i) - l.get(i - 1);
	    i++;
	}
	if (i == n) return true;

	boolean inc = l.get(i) - l.get(i - 1) >= 0;
	prev_diff = l.get(i) - l.get(i - 1);
	i++;
	while (i < n) {
	    if (l.get(i) - l.get(i - 1) == 0) {
		i++;
		continue;
	    }
	    if (inc && prev_diff >= 0) {
		prev_diff = l.get(i) - l.get(i - 1);
		i++;
	    } else if (!inc && prev_diff <= 0) {
		prev_diff = l.get(i) - l.get(i - 1);
		i++;
	    } else {
		return false;
	    }
	}
	return true;
    }

    }
