	hm.put('5',13);
	hm.put('6',17);
	hm.put('7',19);
	hm.put('8',23);
	hm.put('9',29);
	int c = 0;
	for(char d : num.toCharArray()){
	    c += hm.get(d);
	}
	int cnt = 0;
	for(char d : num.toCharArray()){
	    if(hm.get(d) == c){
		cnt++;
	    }
	}
	return cnt;
    }
}
