import java.lang.*;

class Solution {
    /**
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
     */
    public int startsOneEnds(int n) {
	int len = n;
	if (len <= 0) {
	    return -1;
	}
	int[] dp = new int[len + 1];
	dp[0] = dp[1] = 1;
	for (int i = 2; i <= len; i++) {
	    int d = 1;
	    int lastDigit = 0;
	    int count = 0;
	    while (d <= 9) {
		if (lastDigit == 1) {
		    count += (int) Math.pow(10, i-1);
		}
		count += (i == len)? 1 : dp[i - 1];
		lastDigit = d;
		d++;
	    } // end of while
	    dp[i] = count;
	} // end of for
	return dp[len];
    }

}
