class Solution {
    private int longestSubstringLength(String s, int start, int end) {
	Set<Character> set = new HashSet<>();
	for (int i = start; i < end; i++) {
	    char c = s.charAt(i);
	    if (set.contains(c)) {
		return Math.max(longestSubstringLength(s, start, i), longestSubstringLength(s, i + 1, end));
	    }
	    set.add(c);
	}

	return set.size();
    }

    /**
    Given a string, find the length of the longest substring without repeating characters.

    Examples:
    * longestSubstring("abcabcbb") => 3 ( "abc" )
    * longestSubstring("bbbbb") => 1 ( "b" )
