public class Solution {
    public int makeChocolate(int small, int big, int goal) {
        int remain = goal;
        if(goal > small + big * 5) return -1;
        else if(remain - small >= 0) {
            remain -= small;
        } else {
            remain -= small + 5 * big;
        }
        return remain;
    }
}
