# https://leetcode.com/problems/jump-game/
class Solution:
    def jump(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        if len(nums) == 0:
            return 0
        count = 0
        cur = 0
        while cur < len(nums) - 1:
            count += 1
            jump = nums[cur]
            i = cur + 1
            while i < len(nums) and i <= cur + jump:
                if nums[i] + i >= len(nums) - 1:
                    return count + 1
                i += 1
            cur = i
        return count
