	int sum = 0;
	int prod = 1;
	for (int i : arr) {
	    if (i == 0) prod = 0;
	    else if (i > 0) prod *= 1;
	    else prod *= -1;
	    sum += Math.abs(i);
	}
	return Optional.of(sum * prod);
    }
