    public List<Integer> inOrderTraversal(TreeNode root) {
	List<Integer> ans = new ArrayList<>();
	LinkedList<TreeNode> stack = new LinkedList<>();
	TreeNode curr = root;
	while (curr!= null ||!stack.isEmpty()) {
	    while (curr!= null) {
		stack.add(curr);
		curr = curr.left;
	    }
	    curr = stack.pollLast();
	    ans.add(curr.data);
	    curr = curr.right;
	}
	return ans;
    }
}
