package com.leetcode.binarysearch;

import java.util.*;
import java.lang.*;


class Solution {
    /**
    Given two strings s and t of equal length,
    the Hamming distance between s and t is defined as
    the number of positions at which the corresponding
    characters are different.

    Return the minimum Hamming distance between s and t.

    Input: s = "leetcode", t = "practice"
    Output: 5
    Explanation: We can convert s to t by
    inserting five 'p' characters in s
    so that the resulting string is "ppaleetcode". Then all characters
    that were in s but were not in t are 'p'.
    The answer is 5 because the string "ppaleetcode"
    contains 5 'p' characters.
     */

    public int minSteps(String s, String t) {
        int[] freq = new int[26];
        for (int i = 0; i < s.length(); i++)
            freq[s.charAt(i) - 'a']++;
        for (int i = 0; i < t.length(); i++)
            freq[t.charAt(i) - 'a']--;
        int ret = 0;
        for (int i = 0; i < 26; i++)
            ret += Math.abs(freq[i]);
        return ret;
    }
}
public class Main {
    public static void main(String[] args) {
        Solution s = new Solution();
        List<Boolean> correct = Arrays.asList(
                s.checkIfLastCharIsALetter("apple" ) == false,
                s.checkIfLastCharIsALetter("apple pi e" ) == true,
                s.checkIfLastCharIsALetter("eeeee" ) == false,
                s.checkIfLastCharIsALetter("A" ) == true,
                s.checkIfLastCharIsALetter("Pumpkin pie " ) == false,
                s.checkIfLastCharIsALetter("Pumpkin pie 1" ) == false,
                s.checkIfLastCharIsALetter("" ) == false,
                s.checkIfLastCharIsALetter("eeeee e " ) == false,
                s.checkIfLastCharIsALetter("apple pie" ) == false,
                s.checkIfLastCharIsALetter("apple pi e " ) == false
        );
        if (correct.contains(false)) {
            throw new AssertionError();
        }
    }
}

