class Solution {
    /**
    There are eight planets in our solar system: the closerst to the Sun
    is Mercury, the next one is Venus, then Earth, Mars, Jupiter, Saturn,
    Uranus, Neptune.
    Write a function that takes two planet names as strings planet1 and planet2.
    The function should return a tuple containing all planets whose orbits are
    located between the orbit of planet1 and the orbit of planet2, sorted by
    the proximity to the sun.
    The function should return an empty tuple if planet1 or planet2
    are not correct planet names.
    Examples
    bf("Jupiter", "Neptune") ==> ["Saturn", "Uranus"]
    bf("Earth", "Mercury") ==> ["Venus"]
    bf("Mercury", "Uranus") ==> ["Venus", "Earth", "Mars", "Jupiter", "Saturn"]
     */
    public List<String> bf(String planet1, String planet2) {
/*
1.Create a map and put all planets in it in the order of their distance from the sun.
2.Get the index1 and index2 of 2 planets of the map.
3.Create a List to hold all the planets in the middle.
4.Use for loop to add the values in the middle.
5.return the list.
 */
        Map<String, String> map = new HashMap<>();
        map.put("Mercury", "Venus");
        map.put("Venus", "Earth");
        map.put("Earth", "Mars");
        map.put("Mars", "Jupiter");
        map.put("Jupiter", "Saturn");
        map.put("Saturn", "Uranus");
        map.put("Uranus", "Neptune");
        List<String> list = new ArrayList<>();
        if (!map.containsKey(planet1) ||!map.containsKey(planet2)) {
            return list;
