class Solution {
    /**
     * Determine whether the sum of every contiguous subarray in a list is equal to a given number.
     *
     * Example:
     * >>> array = [6, 8, -3, -2, 5, -4, 10, -1, 2], k = 6
     * >>> subarraySumEqualsK(array, k) == true
     * >>> array = [1, 2, 3, 4, 5, 6], k = 7
     * >>> subarraySumEqualsK(array, k) == false
     */
    public boolean subarraySumEqualsK(int[] array, int k) {
//      Your code here
        int sum = 0;
        Map<Integer, Integer> map = new HashMap<Integer, Integer>();
        map.put(sum, 1);
        for (int i = 0; i < array.length; i++) {
            sum += array[i];
            if (map.containsKey(sum - k)) {
                return true;
            }
            if (!map.containsKey(sum)) {
                map.put(sum, 1);
            } else {
                map.put(sum, map.get(sum) + 1);
            }
        }
        return false;
    }
}
