import sys

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self, head):
        self.head = head
        self.prev = None

def main():
    """
    Main function to test implementation of linked list
    """
    head = Node(1)
    linkedlist = LinkedList(head)
    linkedlist.add_node(3)
    linkedlist.add_node(4)
    linkedlist.add_node(5)
    linkedlist.reverse_list()
    print_list(linkedlist.head)

def print_list(head):
    """
    Function to print the linked list
    """
    while head:
        print(head.data)
        head = head.next

def add_node(self, data):
    """
    Function to add a node to the end of the linked list
    """
    new_node = Node(data)
    if self.head == None:
        self.head = new_node
    else:
        current_node = self.head
        while current_node.next:
            current_node = current_node.next
        current_node.next = new_node

def reverse_list(self):
    """
    Function to reverse the linked list
    """
    current = self.head
    prev = None
    while current:
        next = current.next
        current.next = prev
        prev = current
        current = next
    self.head = prev


